  "aplomb": {label:"Fassung",gender:"die",plural:"—", ex5:[{t:1,s:"Sie behielt bei den schwierigen Fragen ihre Fassung."},{t:2,s:"Selbst in der Krise bewahrte er seine Fassung."},{t:3,s:"Der junge Schauspieler trat mit erstaunlicher Fassung auf der Bühne auf."},{t:4,s:"Es ist bewundernswert, wie er seine Fassung in Stresssituationen behält."},{t:5,s:"Sie verlor ihre Fassung nicht, obwohl die Situation sehr angespannt war."}]},
  "apnea": {label:"Apnoe",gender:"die",plural:"Apnoen", ex5:[{t:1,s:"Er benutzt ein spezielles Gerät, um seine Schlafapnoe zu behandeln."},{t:2,s:"Schlafapnoe kann dazu führen, dass man sich tagsüber müde fühlt."},{t:3,s:"Mein Vater schnarcht laut wegen seiner Apnoe."},{t:4,s:"Die Diagnose Schlafapnoe sollte ernst genommen werden."},{t:5,s:"Durch die Behandlung der Apnoe hat sich seine Schlafqualität verbessert."}]},
