  "apogee": {label:"Apogäum",gender:"das",plural:"Apogäen", ex5:[{t:1,s:"Die Band erreichte mit diesem Hit-Album den Apogäum ihrer Karriere."},{t:2,s:"Die Raumstation befindet sich derzeit im Apogäum ihrer Umlaufbahn."},{t:3,s:"Dieses Gemälde stellt das Apogäum seines künstlerischen Schaffens dar."},{t:4,s:"Er stand am Apogäum seines Erfolges."},{t:5,s:"Das Apogäum des Mondes ist der Punkt der größten Entfernung zur Erde."}]},
  "apolitical": {label:"apolitisch",gender:"",plural:"—", ex5:[{t:1,s:"Er zieht es vor, in seinem täglichen Leben apolitisch zu bleiben."},{t:2,s:"Die Organisation behauptet, rein apolitisch zu sein."},{t:3,s:"Es ist heutzutage schwer, eine apolitische Diskussion zu finden."},{t:4,s:"Sie verhält sich in beruflichen Fragen völlig apolitisch."},{t:5,s:"Manche Menschen sind bewusst apolitisch eingestellt."}]},
