  "apologies": {label:"Entschuldigung",gender:"die",plural:"Entschuldigungen", ex5:[{t:1,s:"Bitte akzeptieren Sie meine aufrichtige Entschuldigung für die Verspätung."},{t:2,s:"Er schickte ihr nach dem Streit schriftliche Entschuldigungen."},{t:3,s:"Für so einen kleinen Fehler sind keine Entschuldigungen nötig."},{t:4,s:"Sie nahm seine Entschuldigung sofort an."},{t:5,s:"Er brachte viele Entschuldigungen für sein Verhalten vor."}]},
  "apologise": {label:"sich entschuldigen",gender:"",plural:"—", ex5:[{t:1,s:"Du solltest dich bei deiner Schwester entschuldigen."},{t:2,s:"Ich möchte mich für meine Verspätung entschuldigen."},{t:3,s:"Sie wollte sich auch nach dem Streit nicht entschuldigen."},{t:4,s:"Man muss sich entschuldigen, wenn man einen Fehler macht."},{t:5,s:"Er weigert sich, sich bei mir zu entschuldigen."}]},
  "apologised": {label:"sich entschuldigte",gender:"",plural:"—", ex5:[{t:1,s:"Er entschuldigte sich für seine Verspätung zum Treffen."},{t:2,s:"Sie entschuldigte sich aufrichtig bei ihrer besten Freundin."},{t:3,s:"Die Firma entschuldigte sich bei allen Kunden für den Fehler."},{t:4,s:"Er hat sich gestern bei mir entschuldigt."},{t:5,s:"Sie entschuldigte sich höflich für die Umstände."}]},
  "apologising": {label:"sich entschuldigend",gender:"",plural:"—", ex5:[{t:1,s:"Er verbrachte den ganzen Nachmittag damit, sich für sein unhöfliches Verhalten zu entschuldigen."},{t:2,s:"Hör auf, dich zu entschuldigen; es war nur ein kleiner Fehler."},{t:3,s:"Sie ist nicht gut darin, sich zu entschuldigen, selbst wenn sie unrecht hat."},{t:4,s:"Er kam sich entschuldigend auf mich zu."},{t:5,s:"Sie schaute mich entschuldigend an."}]},
  "apologist": {label:"Apologet",gender:"der",plural:"Apologeten", ex5:[{t:1,s:"Er ist ein lautstarker Apologet der neuen Regierungspolitik."},{t:2,s:"Der Autor agiert als Apologet für die historische Figur."},{t:3,s:"Kritiker nannten ihn einen Apologeten für die Gier der Konzerne."},{t:4,s:"Er ist ein bekannter Apologet dieser Lehre."},{t:5,s:"Die Apologeten der alten Schule denken anders."}]},
  "apologize": {label:"sich entschuldigen",gender:"",plural:"—", ex5:[{t:1,s:"Sie entschuldigen sich."},{t:2,s:"Die Notiz ist sich entschuldigend."},{t:3,s:"Wir entschuldigen uns für die Verspätung."},{t:4,s:"Sie müssen sich dafür entschuldigen."},{t:5,s:"Wir entschuldigen uns bei Ihnen für den Vorfall."}]},
  "apologized": {label:"sich entschuldigte",gender:"",plural:"—", ex5:[{t:1,s:"Er entschuldigte sich."},{t:2,s:"Der Fehler wurde entschuldigt."},{t:3,s:"Sie entschuldigten sich bei uns."},{t:4,s:"Er hat sich für den Vorfall entschuldigt."},{t:5,s:"Sie entschuldigte sich formell bei der Gruppe."}]},
  "apologizes": {label:"entschuldigt sich",gender:"",plural:"—", ex5:[{t:1,s:"Er entschuldigt sich immer, wenn er einen Fehler macht."},{t:2,s:"Sie entschuldigt sich für ihre Verspätung beim Treffen."},{t:3,s:"Mein Bruder entschuldigt sich bei mir, wann immer wir streiten."},{t:4,s:"Er entschuldigt sich höflich für das Missverständnis."},{t:5,s:"Sie entschuldigt sich jedes Mal, wenn sie etwas vergisst."}]},
  "apologizing": {label:"sich entschuldigen",gender:"",plural:"—", ex5:[{t:1,s:"Er hat den ganzen Nachmittag damit verbracht, sich für seinen Fehler zu entschuldigen."},{t:2,s:"Es hat keinen Sinn, sich zu entschuldigen, wenn man es nicht ernst meint."},{t:3,s:"Sie entschuldigt sich ständig dafür, dass sie zu spät zum Meeting gekommen ist."},{t:4,s:"Man sollte sich aufrichtig für sein Verhalten entschuldigen."},{t:5,s:"Du musst dich nicht für alles entschuldigen."}]},
